const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Redact anything that looks like a credential before it leaves n8n.
const redact = (s) => String(s ?? '')
  .replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***')
  .replace(/((?:api_)?token|key|secret|password)=[^&\s]+/gi, '$1=***');
const e = $json;
const workflow = e.workflow?.name || 'unknown workflow';
const node = e.execution?.lastNodeExecuted || e.trigger?.node?.name || 'unknown node';
const error = e.execution?.error?.message || e.trigger?.error?.message || 'Unknown error';
const url = e.execution?.url;
let text = `<b>n8n workflow failed</b>\nWorkflow: ${esc(workflow)}\nNode: ${esc(node)}\nError: ${esc(redact(error)).slice(0, 500)}`;
if (url) text += `\n<a href="${esc(url)}">Open execution</a>`;
return [{ json: { text } }];
